  getr R (reg 18) = Z_to_bv 64 (fb + 64) -> getr R (reg 20) = Z_to_bv 64 d -> getr R (reg 21) = Z_to_bv 64 w ->
  getr R (reg 22) = Z_to_bv 64 (fb + 376 + 1) -> kept6 R ->
  0 <= d <= w -> d <= PM.CHUNK -> 1 <= w <= len ->
